(()=>{"use strict";const b=document.querySelector(".menu-btn"),n=document.querySelector("#site-nav");if(!b||!n)return;b.addEventListener("click",()=>{const o=b.getAttribute("aria-expanded")==="true";b.setAttribute("aria-expanded",String(!o));n.classList.toggle("open",!o)});n.addEventListener("click",e=>{if(e.target.matches("a")){n.classList.remove("open");b.setAttribute("aria-expanded","false")}});window.addEventListener("keydown",e=>{if(e.key==="Escape"){n.classList.remove("open");b.setAttribute("aria-expanded","false")}})})();